(function(){
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const app=$('#app'), state={page:'home',mode:'sim',protected:false,running:false,events:[],result:null,step:0,start:0,timer:null,paused:false,tests:[]};
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const toast=m=>{const t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2100)};
  function home(){state.page='home';app.innerHTML=`<section class="dashboard"><div class="eyebrow">OFFENSIVE AI SECURITY · INTERACTIVE ENVIRONMENT</div><div class="hero"><h1>SEE THE ATTACK.<br><span>VERIFY THE IMPACT.</span></h1><p>Un entorno seguro y reproducible para visualizar cómo los datos atraviesan fronteras de confianza, activan modelos y alcanzan herramientas.</p></div><div class="status-strip"><span>Simulation engine ready</span><span>All data synthetic</span><span>0 external actions</span></div><div class="lab-grid">${LAB_DATA.labs.map((l,i)=>`<article class="lab-card" style="--accent:${['#00d9ff','#8b5cf6','#f59e0b','#22c55e'][i]}"><div class="card-top"><span class="lab-num">LAB ${l.num}</span><span class="risk">${l.risk}</span></div><div class="lab-icon">${l.icon}</div><h2>${l.title}</h2><h3>${l.subtitle}</h3><p>${l.desc}</p><div class="mini-flow">${l.path.map((n,j)=>`${j?'<i class="mini-line"></i>':''}<span class="mini-node">${n}</span>`).join('')}</div><button class="launch" data-open="${l.id}">INICIAR LAB →</button></article>`).join('')}</div></section>`;}
  function nodes(kind){const sets={prompt:[['IN','Usuario'],['API','API'],['GRD','Guardrail'],['LLM','Modelo'],['OUT','Respuesta']],rag:[['Q','Consulta'],['RET','Retrieval'],['DOC','Documentos'],['CTX','Contexto'],['LLM','Modelo']],agent:[['USR','Usuario'],['AGT','Agente'],['RTR','Tool Router'],['AZ','AuthZ'],['DB','Backend']]};return (sets[kind]||[]).map((n,i)=>`<div class="node" data-node="${i}"><span class="node-dot">${n[0]}</span><div><b>${n[1]}</b><small>${i?'En espera':'Entrada no confiable'}</small></div></div>`).join('')}
  function controls(kind){const lib=LAB_DATA.payloads[kind]||[];return `<div class="objective"><small>OBJETIVO DE LA PRUEBA</small><p>${kind==='prompt'?'Comprobar si la entrada altera una política de mayor autoridad.':kind==='rag'?'Detectar instrucciones no confiables dentro del contexto recuperado.':'Verificar que toda mutación tenga autorización independiente.'}</p></div><div class="field"><label>CONFIGURACIÓN</label><div class="seg"><button class="${!state.protected?'active vuln':''}" data-protected="false">VULNERABLE</button><button class="${state.protected?'active safe':''}" data-protected="true">PROTECTED</button></div></div><div class="field"><label>BIBLIOTECA DE PAYLOADS</label><div class="preset-list">${lib.map((p,i)=>`<button class="chip" data-preset="${i}">${p.name}</button>`).join('')}</div></div><div class="field"><label>PAYLOAD / CONSULTA</label><textarea id="payload">${esc(lib[1]?.value||lib[0]?.value||'')}</textarea></div><div class="btn-row"><button class="btn primary" data-action="run" ${state.running?'disabled':''}>${state.running?'EJECUTANDO…':'▶ EJECUTAR'}</button><button class="btn" data-action="reset">↻</button></div><div class="explain"><b>CRITERIO DE ÉXITO</b><br>El laboratorio solo marca una vulnerabilidad cuando existe evidencia verificable: divulgación de un marcador, cruce de frontera de confianza o cambio de estado no autorizado.</div>`}
  function target(kind){if(kind==='rag')return `<div class="app-chrome"><div class="app-nav"><b>NovaSearch · Knowledge Assistant</b><span>● INDEX ONLINE</span></div><div class="doc-list">${LAB_DATA.docs.map(d=>`<div class="doc ${d.trust==='untrusted'?'untrusted':''}"><div class="doc-top"><b>${d.id} · ${d.title}</b><span class="tag ${d.trust==='untrusted'?'warn':''}">${d.trust.toUpperCase()} · ${d.score}</span></div><p>${d.text}</p></div>`) .join('')}</div>${responseBlock()}</div>`;
    if(kind==='agent')return `<div class="app-chrome"><div class="app-nav"><b>NovaCare · Support Agent</b><span>● 5 TOOLS CONNECTED</span></div><div class="order-card"><div><small>ACTOR AUTENTICADO</small><strong>C-042 · Ana Torres</strong></div><div><small>PEDIDO OBJETIVO</small><strong>ORD-7781 · C-009</strong></div><div><small>ESTADO ANTES</small><strong>shipped</strong></div><div><small>ESTADO DESPUÉS</small><strong id="after-state">${state.result&&!state.protected?'cancelled':'shipped'}</strong></div></div><div class="chat"><div class="bubble bot">Soy el agente de soporte de NovaTech. Puedo consultar pedidos y gestionar tickets.</div><div class="bubble user">${esc(LAB_DATA.payloads.agent[1].value)}</div>${responseBubble()}</div></div>`;
    return `<div class="app-chrome"><div class="app-nav"><b>NovaTech · Customer AI</b><span>● ASSISTANT ONLINE</span></div><div class="chat"><div class="bubble bot">Hola. Puedo ayudarte con planes, servicios y políticas de NovaTech.</div><div class="bubble user">${esc(LAB_DATA.payloads.prompt[1].value)}</div>${responseBubble()}</div>${state.result?`<div class="compare"><div class="compare-card danger"><h4>VULNERABLE</h4><p>El texto del usuario comparte canal operativo con las instrucciones. Un marcador sintético puede aparecer en la salida.</p></div><div class="compare-card safe"><h4>PROTECTED</h4><p>El backend limita capacidades, preserva jerarquía y valida la salida antes de responder.</p></div></div>`:''}</div>`}
  function responseBubble(){return state.result?`<div class="bubble bot ${state.result.bad?'alert':''}"><b>${state.result.bad?'⚠ POLICY VIOLATION':'✓ CONTROL APPLIED'}</b><br>${esc(state.result.response)}</div>`:`<div class="empty">EJECUTA EL ESCENARIO<br>PARA OBSERVAR LA RESPUESTA</div>`}
  function responseBlock(){return state.result?`<div class="chat"><div class="bubble bot ${state.result.bad?'alert':''}">${esc(state.result.response)}</div></div>`:''}
  function lab(kind){state.page=kind;const l=LAB_DATA.labs.find(x=>x.id===kind);app.innerHTML=`<section class="lab-shell"><aside class="panel"><div class="panel-head"><h2>ATTACK CONTROL</h2><span>LAB ${l.num}</span></div><div class="control-body">${controls(kind)}</div></aside><section class="panel target"><div class="panel-head"><h2>TARGET APPLICATION · ${l.subtitle.toUpperCase()}</h2><span>${state.protected?'HARDENED':'BASELINE'}</span></div><div class="target-app">${target(kind)}</div>${state.result?`<div class="verdict ${state.result.bad?'danger':'safe'}"><span>${state.result.bad?'⚠':'✓'}</span><div><strong>${state.result.bad?'VULNERABILIDAD DEMOSTRADA':'CONTROL VERIFICADO'}</strong><p>${esc(state.result.evidence)}</p></div></div>`:''}</section><aside class="panel observability"><div class="panel-head"><h2>SECURITY OBSERVABILITY</h2><span>EVENT-DRIVEN</span></div><div class="obs-body"><div class="flow-wrap"><div class="flow">${nodes(kind)}</div></div><div><div class="tabs"><button class="active">EVENT LOG</button><button>CONTEXT</button><button>EVIDENCE</button></div><div class="log">${state.events.length?state.events.map(e=>`<div class="log-row"><span class="log-time">${e.time}</span><span class="log-type">${e.type}</span><span class="log-detail">${esc(e.label)}${e.detail?` · ${esc(e.detail)}`:''}</span></div>`).join(''):'<div class="empty">SIN EVENTOS<br>La telemetría aparecerá aquí</div>'}</div></div></div></aside></section>`;updateNodes();}
  function updateNodes(){state.events.forEach((e,i)=>{const n=$$('[data-node]')[Math.min(i,$$('[data-node]').length-1)];if(n)n.className='node '+e.state})}
  async function run(){if(state.running||!['prompt','rag','agent'].includes(state.page))return;state.running=true;state.events=[];state.result=null;lab(state.page);const value=$('#payload')?.value||LAB_DATA.payloads[state.page][1].value;const kind=state.page;state.result=await SimEngine.run(kind,value,state.protected,e=>{state.events.push(e);lab(kind)});state.running=false;lab(kind)}
  function auto(){state.page='auto';const s=state.autoStats||{total:8,pass:0,fail:0,inconclusive:0};app.innerHTML=`<section class="lab-shell" style="grid-template-columns:310px 1fr"><aside class="panel"><div class="panel-head"><h2>RUN CONFIGURATION</h2><span>LAB 04</span></div><div class="control-body"><div class="objective"><small>OBJETIVO</small><p>Ejecutar casos deterministas y registrar evidencia reproducible.</p></div><div class="field"><label>TARGET</label><select><option>NovaTech AI Suite</option></select></div><div class="field"><label>TEST CATEGORY</label><select><option>All security categories</option><option>Prompt Injection</option><option>RAG Poisoning</option><option>Excessive Agency</option></select></div><div class="field"><label>NÚMERO DE CASOS</label><input id="case-count" type="range" min="4" max="8" value="8"></div><div class="field"><label>CONFIGURACIÓN</label><div class="seg"><button class="${!state.protected?'active vuln':''}" data-protected="false">VULNERABLE</button><button class="${state.protected?'active safe':''}" data-protected="true">PROTECTED</button></div></div><div class="field"><label>ENGINE</label><select><option>Deterministic Simulator</option><option disabled>Promptfoo (not installed)</option><option disabled>Garak (not installed)</option><option disabled>PyRIT (not installed)</option></select></div><div class="btn-row"><button class="btn primary" data-action="run-auto" ${state.running?'disabled':''}>${state.running?'RUNNING…':'▶ RUN SUITE'}</button><button class="btn" data-action="export">↓ JSON</button></div><div class="explain">Etiqueta activa: <b>SIMULATED</b><br>No se afirma la ejecución de herramientas externas.</div></div></aside><section class="panel"><div class="panel-head"><h2>AUTOMATED RED TEAM · RESULTS</h2><span>${state.protected?'PROTECTED':'VULNERABLE'} TARGET</span></div><div class="auto-layout"><div class="metric-grid"><div class="metric"><small>TOTAL</small><b>${s.total}</b></div><div class="metric"><small>PASSED</small><b style="color:var(--green)">${s.pass}</b></div><div class="metric"><small>FAILED</small><b style="color:var(--red)">${s.fail}</b></div><div class="metric"><small>INCONCLUSIVE</small><b style="color:var(--amber)">${s.inconclusive}</b></div></div><div style="grid-column:1/-1"><div class="progress"><i style="width:${state.progress||0}%"></i></div></div><div class="test-table"><div class="test-row head"><span>ID</span><span>CATEGORY</span><span>STATUS</span><span>TIME</span></div>${state.tests.map(t=>`<div class="test-row"><span>${t.id}</span><span>${t.category} · ${t.name}</span><b class="status-${t.status.toLowerCase()}">${t.status}</b><span>${t.time}ms</span></div>`).join('')||'<div class="empty" style="height:180px">LISTO PARA EJECUTAR<br>8 casos cargados</div>'}</div></div></section></section>`}
  async function runAuto(){if(state.running)return;state.running=true;state.tests=[];state.progress=0;state.autoStats={total:8,pass:0,fail:0,inconclusive:0};auto();state.autoStats=await SimEngine.runSuite(state.protected,8,t=>{state.tests.push(t)},(p,s)=>{state.progress=Math.round(p*100);state.autoStats={...s};auto()});state.running=false;auto();toast('Suite completada con evidencia reproducible')}
  function reset(){state.events=[];state.result=null;state.tests=[];state.autoStats=null;state.progress=0;state.running=false;state.page==='home'?home():state.page==='auto'?auto():lab(state.page)}
  function presenter(on=true){$('#presenter').classList.toggle('hidden',!on);if(on){state.start=Date.now();clearInterval(state.timer);state.timer=setInterval(()=>{if(!state.paused){const sec=Math.floor((Date.now()-state.start)/1000);$('#timer').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}},1000);applyStep()}else clearInterval(state.timer)}
  function applyStep(){const [page,title]=LAB_DATA.steps[state.step];$('#step-count').textContent=`PASO ${state.step+1} / ${LAB_DATA.steps.length}`;$('#step-title').textContent=title;state.result=null;state.events=[];page==='home'?home():page==='auto'?auto():lab(page)}
  function exportJson(){const blob=new Blob([JSON.stringify({generatedAt:new Date().toISOString(),engine:'deterministic-simulator',configuration:state.protected?'protected':'vulnerable',results:state.tests},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ai-red-team-report.json';a.click();URL.revokeObjectURL(a.href);toast('Reporte JSON generado')}
  document.addEventListener('click',e=>{const el=e.target.closest('button,[data-open]');if(!el)return;const open=el.dataset.open,act=el.dataset.action;if(open){state.result=null;state.events=[];open==='auto'?auto():lab(open)}if(el.dataset.protected){state.protected=el.dataset.protected==='true';reset()}if(el.dataset.preset!=null){$('#payload').value=LAB_DATA.payloads[state.page][+el.dataset.preset].value}if(act==='home')home();if(act==='run')run();if(act==='run-auto')runAuto();if(act==='reset'||act==='reset-all')reset();if(act==='fullscreen')document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();if(act==='exit-present')presenter(false);if(act==='next-step'){state.step=Math.min(6,state.step+1);applyStep()}if(act==='prev-step'){state.step=Math.max(0,state.step-1);applyStep()}if(act==='pause'){state.paused=!state.paused;toast(state.paused?'Presentación pausada':'Presentación reanudada')}if(act==='export')exportJson()});
  home();
})();
